#!/usr/bin/env python3
"""SGR-aware screen parser: locate the editor cursor + selection from a `capture-pane -e`."""
import re

SGR_RE = re.compile(r"\x1b\[([0-9;]*)m")


def parse_line(line):
    """-> list of (char, fg, bg, bold) cells"""
    cells = []
    fg = bg = None
    bold = False
    i = 0
    while i < len(line):
        m = SGR_RE.match(line, i)
        if m:
            params = m.group(1)
            toks = params.split(";") if params else ["0"]
            j = 0
            while j < len(toks):
                t = toks[j]
                if t == "" or t == "0":
                    fg = bg = None; bold = False
                elif t == "1":
                    bold = True
                elif t == "22":
                    bold = False
                elif t == "39":
                    fg = None
                elif t == "49":
                    bg = None
                elif t == "38":
                    if j + 1 < len(toks) and toks[j+1] == "5":
                        fg = "c" + toks[j+2]; j += 2
                    elif j + 1 < len(toks) and toks[j+1] == "2":
                        fg = "rgb(%s,%s,%s)" % (toks[j+2], toks[j+3], toks[j+4]); j += 4
                elif t == "48":
                    if j + 1 < len(toks) and toks[j+1] == "5":
                        bg = "c" + toks[j+2]; j += 2
                    elif j + 1 < len(toks) and toks[j+1] == "2":
                        bg = "rgb(%s,%s,%s)" % (toks[j+2], toks[j+3], toks[j+4]); j += 4
                elif t.isdigit() and 30 <= int(t) <= 37:
                    fg = "b" + t
                elif t.isdigit() and 40 <= int(t) <= 47:
                    bg = "b" + t
                elif t.isdigit() and 90 <= int(t) <= 97:
                    fg = "B" + t
                elif t.isdigit() and 100 <= int(t) <= 107:
                    bg = "B" + t
                j += 1
            i = m.end()
            continue
        cells.append((line[i], fg, bg, bold))
        i += 1
    return cells


CURSOR_BG = {"c15": "NORMAL", "c10": "INSERT", "c4": "VISUAL",
             "c7": "NORMAL?", "c12": "listsel"}


def annotate(capE, mark_bgs=("c15", "c10", "c4")):
    """Return plain screen with a '|' marker line under cursor cells."""
    out = []
    for row in capE.split("\n"):
        cells = parse_line(row)
        text = "".join(c[0] for c in cells)
        marks = ["".join("^" if c[2] == b else " " for c in cells) for b in mark_bgs]
        out.append(text)
        for b, mk in zip(mark_bgs, marks):
            if mk.strip():
                out.append(mk.rstrip() + "   <== bg=%s (%s)" % (b, CURSOR_BG.get(b, "?")))
    return "\n".join(out)


def cursor_cells(capE, bgs=("c15", "c10", "c4")):
    res = []
    for y, row in enumerate(capE.split("\n")):
        for x, c in enumerate(parse_line(row)):
            if c[2] in bgs:
                res.append((y, x, c[0], c[2]))
    return res


if __name__ == "__main__":
    import sys
    print(annotate(sys.stdin.read()))
